<?php
namespace App\Http\Controllers;
use App\Models\Admin;use App\Models\Store;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class HouseStoreController extends Controller {
 public function show(Request $r):JsonResponse{$this->auth($r);return response()->json($this->shape(Store::primary()??Store::firstOrCreate(['setup_key'=>Store::PRIMARY_KEY],['name'=>config('app.name')])));}
 public function save(Request $r):JsonResponse{$this->auth($r);$d=$r->validate(['store_name'=>['sometimes','required','string','max:255'],'sku_prefix'=>['sometimes','required','regex:/^[A-Za-z0-9]{4}$/'],'email'=>['sometimes','required','email','max:255'],'phone'=>['sometimes','required','regex:/^01[3-9][0-9]{8}$/'],'address_line'=>['sometimes','required_with:address_area,address_district','string','max:255'],'address_area'=>['sometimes','required_with:address_line,address_district','string','max:255'],'address_district'=>['sometimes','required_with:address_line,address_area','string','max:255'],'store_logo'=>['nullable','file','image','max:5120'],'store_logo_media_id'=>['sometimes','nullable','integer','exists:media_assets,id'],'store_logo_url'=>['sometimes','nullable','url','max:2048'],'clear_store_logo'=>['sometimes','boolean']]);$store=Store::firstOrCreate(['setup_key'=>Store::PRIMARY_KEY],['name'=>config('app.name')]);$update=[];if(array_key_exists('store_name',$d))$update['name']=trim($d['store_name']);if(array_key_exists('sku_prefix',$d))$update['sku_prefix']=strtoupper($d['sku_prefix']);if(array_key_exists('email',$d))$update['support_email']=$d['email'];if(array_key_exists('phone',$d))$update['support_phone']=$d['phone'];$addressSent=array_key_exists('address_line',$d)||array_key_exists('address_area',$d)||array_key_exists('address_district',$d);if($addressSent){$update['address_line']=$d['address_line'];$update['address_area']=$d['address_area'];$update['address_district']=$d['address_district'];$update['store_address']=implode(', ',[$d['address_line'],$d['address_area'],$d['address_district']]);}$logo=$r->boolean('clear_store_logo')?null:$store->logo;if($r->hasFile('store_logo')){$logo=app(\App\Services\MediaUploadService::class)->upload($r->file('store_logo'),'stores');}elseif(!$r->boolean('clear_store_logo')&&($r->has('store_logo_media_id')||$r->has('store_logo_url'))){$logo=app(\App\Services\LibraryMediaService::class)->image($d['store_logo_media_id']??null,$d['store_logo_url']??null,null,true);}$update['logo']=$logo;$store->update($update);return response()->json($this->shape($store->fresh()));}
 private function shape(Store $s):array{return ['store_name'=>$s->name,'store_logo'=>$s->logo,'email'=>$s->support_email,'phone'=>$s->support_phone,'address_line'=>$s->address_line,'address_area'=>$s->address_area,'address_district'=>$s->address_district,'sku_prefix'=>$s->sku_prefix,'joined_at'=>$s->created_at?->toDateString()];}
 private function auth(Request $r):void{$a=$r->user();abort_unless($a instanceof Admin&&$a->role==='super_admin',403);}
}
